from decimal import Decimal, getcontext, ROUND_HALF_UP, ROUND_DOWN, InvalidOperation

getcontext().prec = 80

Q2 = Decimal("0.01")

PARAM_KEYS = [
    "DIAS_MAX_DENUNCIA", "DIAS_MAX_DENUNCIA_VIDA", "DEDUCIBLE_MINIMO",
    "PCT_DESCUENTO_DED_VIP", "TOLERANCIA_MORA_VIP", "MAX_SINIESTROS_ANUAL",
    "PCT_PENALIZACION_SINIEST", "UMBRAL_RETENCION", "TASA_RETENCION",
    "TOPE_AUTO_APROBACION", "DIAS_ALERTA_FRAUDE", "PCT_ALERTA_FRAUDE",
]


class ParamMissing(Exception):
    pass


def r2(x):
    # ROUND(x, 2) de Oracle: mitad alejandose de cero
    return Decimal(x).quantize(Q2, rounding=ROUND_HALF_UP)


def store_num_14_2(x):
    # Asignacion a NUMBER(14,2): Oracle redondea a la escala del destino
    return Decimal(x).quantize(Q2, rounding=ROUND_HALF_UP)


def fmt2(x):
    return str(Decimal(x).quantize(Q2, rounding=ROUND_HALF_UP))


def to_dec(s, default="0"):
    if s is None:
        return Decimal(default)
    t = str(s).strip()
    if t == "" or t.lower() in ("null", "none"):
        return Decimal(default)
    try:
        return Decimal(t)
    except InvalidOperation:
        return Decimal(default)


def to_int(s, default=0):
    d = to_dec(s, str(default))
    return int(d.to_integral_value(rounding=ROUND_DOWN))


def to_bool(s):
    if isinstance(s, bool):
        return s
    t = str(s if s is not None else "").strip().upper()
    return t in ("TRUE", "1", "Y", "YES", "S", "SI", "T")


def days_from_civil(y, m, d):
    y2 = y - 1 if m <= 2 else y
    era = (y2 if y2 >= 0 else y2 - 399) // 400
    yoe = y2 - era * 400
    mp = (m + 9) % 12
    doy = (153 * mp + 2) // 5 + d - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe - 719468


def parse_date(s):
    t = str(s if s is not None else "").strip()
    t = t.replace("/", "-")
    if "T" in t:
        t = t.split("T")[0]
    if " " in t:
        t = t.split(" ")[0]
    parts = t.split("-")
    if len(parts) >= 3:
        if len(parts[0]) == 4:
            y, m, d = int(parts[0]), int(parts[1]), int(parts[2])
        else:
            d, m, y = int(parts[0]), int(parts[1]), int(parts[2])
        return days_from_civil(y, m, d)
    if len(t) == 8 and t.isdigit():
        return days_from_civil(int(t[0:4]), int(t[4:6]), int(t[6:8]))
    raise ValueError("fecha invalida")


def strip_q(t):
    t = t.strip()
    while len(t) >= 2 and t[0] in "\"'" and t[-1] in "\"'":
        t = t[1:-1].strip()
    return t


def parse_params(raw, inp):
    result = {}
    if isinstance(raw, dict):
        for k, v in raw.items():
            result[str(k).strip().upper()] = v
    elif raw is not None:
        t = str(raw).strip()
        if t.startswith("{"):
            t = t[1:]
        if t.endswith("}"):
            t = t[:-1]
        t = t.replace("\n", ",").replace(";", ",")
        for item in t.split(","):
            if item.strip() == "":
                continue
            sep = None
            for c in (":", "="):
                if c in item:
                    sep = c
                    break
            if sep is None:
                continue
            k, v = item.split(sep, 1)
            k = strip_q(k).upper()
            v = strip_q(v)
            result[k] = v
    # Respaldo: parametros sueltos en el diccionario de entrada
    for k in PARAM_KEYS:
        if k not in result and k in inp:
            result[k] = inp[k]
    return result


def run(inp: dict) -> dict:
    out = {
        "liquidation_status": "",
        "reason_code": "",
        "base_amount": "0.00",
        "deductible_amount": "0.00",
        "covered_amount": "0.00",
        "withholding_amount": "0.00",
        "net_amount": "0.00",
        "observations": "",
        "claim_new_status": "",
        "error_code": "",
    }

    params = parse_params(inp.get("params"), inp)

    def param(code):
        if code not in params:
            raise ParamMissing(code)
        v = params[code]
        if v is None:
            raise ParamMissing(code)
        t = str(v).strip()
        if t == "" or t.lower() in ("null", "none"):
            raise ParamMissing(code)
        try:
            return Decimal(t)
        except InvalidOperation:
            raise ParamMissing(code)

    obs = {"v": None}

    def add_obs(mark):
        if obs["v"] is None or obs["v"] == "":
            obs["v"] = mark
        else:
            obs["v"] = obs["v"] + ";" + mark

    def finish(estado_liq, motivo, base, ded, cub, ret, neto, observ):
        out["liquidation_status"] = estado_liq
        out["reason_code"] = motivo
        out["base_amount"] = fmt2(base)
        out["deductible_amount"] = fmt2(ded)
        out["covered_amount"] = fmt2(cub)
        out["withholding_amount"] = fmt2(ret)
        out["net_amount"] = fmt2(neto)
        out["observations"] = observ if observ else ""
        if estado_liq == "APROBADA":
            out["claim_new_status"] = "LIQUIDADO"
        elif estado_liq == "RECHAZADA":
            out["claim_new_status"] = "RECHAZADO"
        elif estado_liq == "PENDIENTE_APROBACION":
            out["claim_new_status"] = "PENDIENTE_REVISION"
        out["error_code"] = ""
        return out

    def reject(motivo, observ=None):
        z = Decimal("0")
        return finish("RECHAZADA", motivo, z, z, z, z, z, observ)

    claim_status = str(inp.get("claim_status", "") or "").strip()
    if claim_status != "REGISTRADO":
        out["error_code"] = "ORA-20001"
        return out

    try:
        amount_claimed = to_dec(inp.get("amount_claimed"))
        occ = parse_date(inp.get("occurrence_date"))
        rep = parse_date(inp.get("report_date"))
        policy_status = str(inp.get("policy_status", "") or "").strip()
        branch = str(inp.get("policy_branch", "") or "").strip()
        pstart = parse_date(inp.get("policy_start_date"))
        pend = parse_date(inp.get("policy_end_date"))
        sum_insured = to_dec(inp.get("sum_insured"))
        ded_type = str(inp.get("deductible_type", "") or "").strip()
        ded_value = to_dec(inp.get("deductible_value"))
        pending_premium = to_dec(inp.get("pending_premium"))
        category = str(inp.get("customer_category", "") or "").strip()
        coverage_found = to_bool(inp.get("coverage_found"))
        cov_limit = to_dec(inp.get("coverage_limit"))
        cov_pct = to_dec(inp.get("coverage_percentage"))
        waiting_days = to_int(inp.get("waiting_days"))
        recent_count = to_int(inp.get("recent_liquidated_claims_count"))
        total_indemn = to_dec(inp.get("total_indemnified"))

        # 1.a Estado de la poliza
        if policy_status != "VIGENTE":
            return reject("POLIZA_NO_VIGENTE")

        # 1.b Vigencia (extremos inclusive)
        if occ < pstart or occ > pend:
            return reject("FUERA_DE_VIGENCIA")

        # 1.c Plazo de denuncia
        dias_denuncia = rep - occ
        if branch == "VIDA":
            dias_max = param("DIAS_MAX_DENUNCIA_VIDA")
        else:
            dias_max = param("DIAS_MAX_DENUNCIA")
        if Decimal(dias_denuncia) > dias_max:
            return reject("DENUNCIA_EXTEMPORANEA")

        # 1.d Cobertura contratada
        if not coverage_found:
            return reject("COBERTURA_NO_CONTRATADA")

        # 1.e Carencia
        dias_desde_inicio = occ - pstart
        if dias_desde_inicio < waiting_days:
            return reject("EN_PERIODO_CARENCIA")

        # 1.f Morosidad
        if pending_premium > 0:
            tol = param("TOLERANCIA_MORA_VIP")
            if category == "VIP" and pending_premium <= tol:
                add_obs("TOLERANCIA_MORA_VIP")
            else:
                return reject("PRIMA_EN_MORA", obs["v"])

        # 2.a Monto base
        if amount_claimed > cov_limit:
            monto_base = store_num_14_2(cov_limit)
            add_obs("LIMITE_COBERTURA")
        else:
            monto_base = store_num_14_2(amount_claimed)

        # 2.b Deducible
        if ded_type == "FIJO":
            deducible = store_num_14_2(ded_value)
        else:
            ded_min = param("DEDUCIBLE_MINIMO")
            deducible = store_num_14_2(r2(monto_base * ded_value / Decimal(100)))
            if deducible < ded_min:
                deducible = store_num_14_2(ded_min)
                add_obs("DEDUCIBLE_MINIMO")
        if category == "VIP" and deducible > 0:
            pct_vip = param("PCT_DESCUENTO_DED_VIP")
            deducible = store_num_14_2(r2(deducible * (Decimal(100) - pct_vip) / Decimal(100)))
            add_obs("DESCUENTO_VIP")

        # 2.c Monto cubierto
        cubierto = store_num_14_2(r2((monto_base - deducible) * cov_pct / Decimal(100)))
        if cubierto <= 0:
            return reject("BAJO_DEDUCIBLE", obs["v"])

        # 2.d Siniestralidad
        if Decimal(recent_count) >= param("MAX_SINIESTROS_ANUAL"):
            pen = param("PCT_PENALIZACION_SINIEST")
            cubierto = store_num_14_2(r2(cubierto * (Decimal(100) - pen) / Decimal(100)))
            add_obs("PENALIZACION_SINIESTRALIDAD")

        # 2.e Suma asegurada remanente
        remanente = sum_insured - total_indemn
        if remanente <= 0:
            return reject("SUMA_ASEGURADA_AGOTADA", obs["v"])
        if cubierto > remanente:
            cubierto = store_num_14_2(remanente)
            add_obs("TOPE_SUMA_ASEGURADA")

        # 2.f Retencion (AND con cortocircuito)
        retencion = Decimal("0.00")
        if branch != "VIDA" and cubierto > param("UMBRAL_RETENCION"):
            retencion = store_num_14_2(r2(cubierto * param("TASA_RETENCION") / Decimal(100)))
            add_obs("RETENCION_APLICADA")
        else:
            retencion = Decimal("0.00")

        neto = store_num_14_2(cubierto - retencion)

        # 3. Estado final
        umbral_fraude = r2(cov_limit * param("PCT_ALERTA_FRAUDE") / Decimal(100))
        if Decimal(dias_desde_inicio) <= param("DIAS_ALERTA_FRAUDE") and amount_claimed >= umbral_fraude:
            estado_liq = "PENDIENTE_APROBACION"
            motivo = "SOSPECHA_FRAUDE"
        elif neto > param("TOPE_AUTO_APROBACION"):
            estado_liq = "PENDIENTE_APROBACION"
            motivo = "SUPERA_TOPE_AUTOMATICO"
        else:
            estado_liq = "APROBADA"
            motivo = "LIQUIDACION_AUTOMATICA"

        return finish(estado_liq, motivo, monto_base, deducible, cubierto, retencion, neto, obs["v"])

    except ParamMissing:
        out = {
            "liquidation_status": "",
            "reason_code": "",
            "base_amount": "0.00",
            "deductible_amount": "0.00",
            "covered_amount": "0.00",
            "withholding_amount": "0.00",
            "net_amount": "0.00",
            "observations": "",
            "claim_new_status": "",
            "error_code": "ORA-20010",
        }
        return out
